#include <stdio.h>
#include <ctype.h>

int main(void) {
    long lines = 0, words = 0, chars = 0;
    int c;
    int in_word = 0;
    while ((c = getc(stdin)) != EOF) {
        chars++;
        if (c == '\n')
            lines++;
        if (isspace((unsigned char)c)) {
            if (in_word)
                in_word = 0;
        } else {
            if (!in_word) {
                words++;
                in_word = 1;
            }
        }
    }
    printf("LINES=%ld WORDS=%ld CHARS=%ld\n", lines, words, chars);
    return 0;
}
